To create a Discord bot with a single `ban` command using Discord.js v14, follow these steps:

1. Create a new project in your preferred development environment and install the required dependencies:
```bash
npm init -y
npm install discord.js@14
```
1. Create a new file called `index.js` and add the following code to set up the bot and its interactions:
```javascript
const { Client, Intents, Collection } = require('discord.js');
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');
const fs = require('fs');

const client = new Client({ intents: [Intents.FLAGS.GUILDS, Intents.FLAGS.GUILD_MESSAGES] });

client.commands = new Collection();

const commands = [];

const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));
for (const file of commandFiles) {
    const command = require(`./commands/${file}`);
    commands.push(command.data.toJSON());
    client.commands.set(command.data.name, command);
}

const rest = new REST({ version: '9' }).setToken(process.env.TOKEN);

(async () => {
    try {
        console.log('Registering commands...');
        await rest.put(Routes.applicationGuildCommands(process.env.CLIENT_ID, process.env.GUILD_ID), { body: commands });
        console.log('Successfully registered commands.');
    } catch (error) {
        console.error(error);
    }
})();

client.on('interactionCreate', async interaction => {
    if (!interaction.isChatInputCommand()) return;

    const command = client.commands.get(interaction.commandName);

    if (!command) return;

    try {
        await command.execute(interaction);
    } catch (error) {
        console.error(error);
        if (interaction.replied || interaction.deferred) {
            return interaction.followUp({ content: 'There was an error while executing this command!', ephemeral: true });
        }
        return interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
    }
});

client.login(process.env.TOKEN);
```
1. Create a new folder named `commands` and inside it, create a new file called `ban.js`. Add the following code to define the `ban` command:
```javascript
module.exports = {
    data: {
        name: 'ban',
        description: 'Bans a member',
        options: [
            {
                name: 'user',
                description: 'The user to ban',
                type: 'USER',
                required: true,
            },
            {
                name: 'reason',
                description: 'The reason for the ban',
                type: 'STRING',
            },
        ],
    },
    async execute(interaction) {
        const { MemberResolvable, GuildBanResolver, GuildMember, ModerationManager } = require('discord.js');
        const { MessageEmbed } = require('discord.js');
        const modLogChannel = interaction.guild.channels.cache.find(channel => channel.name === 'mod-logs');

        const targetUser = interaction.options.getMember('user') || (await GuildMember.fetch(interaction.options.getString('user')));
        const reason = interaction.options.getString('reason') ? interaction.options.getString('reason') : 'No reason provided';

        if (!targetUser) {
            return interaction.reply({ content: 'Could not find user.', ephemeral: true });
        }

        if (targetUser.id === interaction.user.id) {
            return interaction.reply({ content: 'You cannot ban yourself!', ephemeral: true });
        }

        if (!ModerationManager.canBan(interaction.member, targetUser)) {
            return interaction.reply({ content: 'You do not have permission to ban this user!', ephemeral: true });
        }

        try {
            await interaction.guild.members.ban(targetUser.id, { reason });

            const banEmbed = new MessageEmbed()
                .setColor('#FF0000')
                .setTitle('User Banned')
                .setDescription(`${targetUser} has been banned by ${interaction.user}.`)
                .addField('Reason', reason)
                .setTimestamp()
                .setFooter({ text: `Requested by ${interaction.user.tag}` });

            if (modLogChannel) {
                return modLogChannel.send({ embeds: [banEmbed] });
            }

            return interaction.reply({ content: `Successfully banned ${targetUser}.`, ephemeral: true });
        } catch (error) {
            console.error(error);
            return interaction.reply({ content: 'There was an error while banning the user!', ephemeral: true });
        }
    },
};
```
1. Replace `process.env.TOKEN` and `process.env.CLIENT_ID` with your actual bot token and client ID respectively. You can get your client ID from the Discord developer portal.
2. Replace `process.env.GUILD_ID` with the ID of the guild where you want to register the commands. If you want the bot to be able to register commands in any server it joins, remove this line.
3. Start the bot by running `node index.js` in your terminal.

Now your bot should be ready to use the `ban` command in the specified guild or any guild where it is invited.

