#include <iostream>
#include <string>
#include <algorithm>

std::string convertMarkdownToHTML(const std::string& markdown) {
    // Replace markdown syntax with corresponding HTML tags
    std::string html = markdown;
    std::replace(html.begin(), html.end(), '#', "<h1>");
    std::replace(html.begin(), html.end(), '*', "<em>");
    std::replace(html.begin(), html.end(), '-', "<li>");
    std::replace(html.begin(), html.end(), '[', "<a href=");
    std::replace(html.begin(), html.end(), ']', "</a>");
    std::replace(html.begin(), html.end(), '(', "<img src=");
    std::replace(html.begin(), html.end(), ')', ">");

    // Close all HTML tags
    size_t startPos, endPos;
    while ((startPos = html.find("<h1")) != std::string::npos) {
        endPos = html.find("</h1>", startPos);
        if (endPos != std::string::npos) {
            html.insert(endPos, "</h1>");
        }
    }
    while ((startPos = html.find("<ul>")) != std::string::npos) {
        endPos = html.find("</ul>", startPos);
        if (endPos != std::string::npos) {
            html.insert(endPos, "</ul>");
        }
    }
    while ((startPos = html.find("<li>")) != std::string::npos) {
        endPos = html.find("</li>", startPos);
        if (endPos != std::string::npos) {
            html.insert(endPos, "</li>");
        }
    }
    while ((startPos = html.find("<a href=")) != std::string::npos) {
        endPos = html.find(">", startPos);
        if (endPos != std::string::npos) {
            html.insert(endPos, "</a>");
        }
    }
    while ((startPos = html.find("<img src=")) != std::string::npos) {
        endPos = html.find(">", startPos);
        if (endPos != std::string::npos) {
            html.insert(endPos, ">");
        }
    }

    return html;
}

int main() {
    std::string markdown = "# Hello World\n\nThis is some *emphasized* text.\n\n[Link](https://www.example.com)\n\n![Image](image.jpg)";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;

    return 0;
}
```
This code defines a `convertMarkdownToHTML` function that takes a reference to a `std::string` containing markdown-formatted text and returns a `std::string` containing the equivalent HTML-formatted text. The function replaces markdown syntax with corresponding HTML tags and then closes all HTML tags.

